import sys
import requests
import datetime

def find_latest_date(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            latest_date = max(
                [datetime.datetime.strptime(date, '%Y-%m-%d') for date in response.text.split()])
            return latest_date.strftime('%Y-%m-%d')
        else:
            return None
    except requests.exceptions.RequestException as e:
        print(f"An error occurred: {e}")
        return None

if __name__ == "__main__":
    url = sys.argv[1]
    latest_date = find_latest_date(url)
    if latest_date:
        print(latest_date)
    else:
        print("Failed to fetch the latest date.")

